export async function freshRun(command: string, args: string[], cwd: string, env: NodeJS.ProcessEnv, control: FreshBuildControlV1, stage: string, completed: number, total: number): Promise<string | undefined> {
  freshCheckpoint(control, stage, completed, total);
  const budgetMs = control.remainingMs();
  if (!Number.isSafeInteger(budgetMs) || budgetMs <= 0 || budgetMs > 86_400_000) throw new Error("fresh process budget must be 1..86400000ms");
  const retained = control.diagnosticsRoot !== undefined;
  const root = control.diagnosticsRoot ?? tmpdir();
  if (!isAbsolute(root) || (retained && !isGeneratedPath(root))) throw new Error("fresh process evidence root must be an absolute directory inside a generated directory");
  const info = lstatSync(root);
  if (!info.isDirectory() || info.isSymbolicLink()) throw new Error("fresh process evidence root must be a regular directory");
  if (command === "cargo" && args.some((arg) => arg === "--message-format" || arg.startsWith("--message-format="))) throw new Error("fresh Cargo diagnostics format is producer-owned");
  const selectedArgs = command === "cargo" ? selectedCargoArguments(cwd, args) : args;
  const argv = command === "cargo" ? [...selectedArgs, "--message-format=json"] : selectedArgs;
  const trace = mkdtempSync(join(root, "fresh-process-"));
  const evidence = retained ? trace : "ephemeral";
  if (retained) console.log("fresh-component-process: stage=" + stage + " evidence=" + evidence);
  const controller = new AbortController();
  const observe = () => { if (control.cancelled() || control.remainingMs() <= 0) controller.abort(); };
  const watch = setInterval(observe, 100);
  let lease: Awaited<ReturnType<typeof acquireCargoBuildLeaseV1>> | undefined;
  try {
    observe();
    if (command === "cargo") lease = await acquireCargoBuildLeaseV1({ directory: repoCacheDirectory(cwd, "agents", "resource-leases"), buildDirectory: cargoDirectories(cwd, env).build, args: selectedArgs, signal: controller.signal, onWait: () => freshCheckpoint(control, "wait-build-lease", completed, total) });
    if (command === "cargo") freshCheckpoint(control, stage, completed, total);
    const builtAtMs = Date.now();
    const directories = command === "cargo" ? cargoDirectories(cwd, env) : undefined;
    const observedEnv = directories ? { ...env, SEMIO_COMPILER_RESOURCE_ROOT: join(directories.build, "semio-compiler-resources") } : env;
    const result = await captureOwnedProcess(command, argv, {
      cwd,
      env: observedEnv,
      budgetMs: Math.min(budgetMs, control.remainingMs()),
      maxOutputBytes: 64 * 1024 * 1024,
      stdoutPath: join(trace, "stdout.jsonl"),
      stderrPath: join(trace, "stderr.txt"),
      cancelled: () => control.cancelled(),
    });
    const reason = result.reason ?? "exit";
    let provenance: string | undefined;
    if (directories) {
      const messages = result.stdout.split(/\r?\n/u).flatMap(line => { try { return [JSON.parse(line)]; } catch { return []; } });
      const manifestIndex = selectedArgs.indexOf("--manifest-path");
      const manifest = resolve(cwd, manifestIndex >= 0 ? selectedArgs[manifestIndex + 1]! : selectedArgs.find(arg => arg.startsWith("--manifest-path="))?.slice("--manifest-path=".length) ?? "Cargo.toml");
      provenance = join(directories.build, "semio-cargo-provenance", "cargo-unit-provenance-" + trace.split(/[\\/]/u).at(-1) + ".json");
      writeCompletedCargoInvocationProvenanceV1(provenance, { manifest, cwd, command, args: argv, buildDirectory: directories.build, builtAtMs, status: result.status ?? -1, cancelled: reason !== "exit", units: messages.filter(message => message.reason === "compiler-artifact").map(message => ({message})), buildScripts: messages.filter(message => message.reason === "build-script-executed") }, new Map(), env.CARGO_HOME);
    }
    writeFileSync(join(trace, "outcome.json"), JSON.stringify({ schema: "semio.plugin.fresh-process/v1", stage, command, args: argv, cargoTargetDir: env.CARGO_TARGET_DIR ?? null, status: result.status, signal: result.signal, reason }) + "\n", {
      flag: "wx",
      mode: 0o600,
    });
    if (result.status !== 0 || result.signal !== null || reason !== "exit") {
      const errors: string[] = [];
      for (const line of result.stdout.split("\n")) {
        try {
          const record = JSON.parse(line);
          if (record?.reason === "compiler-message" && record.message?.level === "error") {
            const rendered = record.message.rendered ?? record.message.message;
            if (typeof rendered === "string") errors.push(rendered.slice(0, 6000));
          }
        } catch {}
        if (errors.length >= 3) break;
      }
      const detail = (errors.length ? errors.join("\n") : result.stderr || result.stdout).slice(-6000);
      throw new Error("fresh component " + reason + " at " + stage + " (status=" + result.status + ", signal=" + result.signal + "); evidence=" + evidence + "\n" + detail);
    }
    freshCheckpoint(control, stage, completed + 1, total);
    return provenance;
  } finally {
    try { lease?.release(); }
    finally { clearInterval(watch); if (!retained) rmSync(trace, { recursive: true, force: true }); }
  }
}

function freshRoot(path: string, label: string): string {
  if (!isAbsolute(path)) throw new Error(`${label} must be absolute`);
  const exact = resolve(path);
  const info = lstatSync(exact);
  if (info.isSymbolicLink() || !info.isDirectory() || readdirSync(exact).length !== 0) throw new Error(`${label} must be an empty regular directory`);
  return realpathSync(exact);
}

export function freshStage(bytes: Uint8Array, destination: string, control: FreshBuildControlV1, stage: string, completed: number, total: number): { byteLength: number; sha256: string } {
  freshCheckpoint(control, stage, completed, total);
  const output = openSync(destination, "wx", 0o600);
  const hash = createHash("sha256");
  let copied = 0;
  let complete = false;
  try {
    while (copied < bytes.byteLength) {
      freshCheckpoint(control, stage, completed, total);
      const chunk = bytes.subarray(copied, Math.min(copied + FRESH_IO_CHUNK_BYTES, bytes.byteLength));
      let written = 0;
      while (written < chunk.byteLength) {
        const count = writeSync(output, chunk, written, chunk.byteLength - written);
        if (!count) throw new Error(`${stage} could not advance snapshot write`);
        written += count;
      }
      hash.update(chunk);
      copied += chunk.byteLength;
    }
    fsyncSync(output);
    freshCheckpoint(control, stage, completed + 1, total);
    complete = true;
    return { byteLength: copied, sha256: hash.digest("hex") };
  } finally {
    closeSync(output);
    if (!complete) rmSync(destination, { force: true });
  }
}

/** 🪪️ Verifies descriptor outputs against the raw snapshot retained before extraction. */
export async function captureFreshComponentInputs(
  repoRoot: string,
  request: Pick<FreshComponentRequestV1, "pluginId" | "componentPackageId">,
  componentBytes: Uint8Array,
  coreBytes: Uint8Array,
  paths: { descriptorPack: string; descriptorJson: string },
  control: FreshBuildControlV1,
) {
  const admission = { remaining: 2 * FRESH_DESCRIPTOR_MAX_BYTES };
  const check = () => freshCheckpoint(control, "verify", 5, 8);
  let descriptorJsonBytes: Uint8Array | undefined, descriptorBytes: Uint8Array | undefined;
  let complete = false;
  try {
    descriptorJsonBytes = readStableBuildFile(paths.descriptorJson, FRESH_DESCRIPTOR_MAX_BYTES, admission, check);
    descriptorBytes = readStableBuildFile(paths.descriptorPack, FRESH_DESCRIPTOR_MAX_BYTES, admission, check);
    const projected = JSON.parse(new TextDecoder("utf-8", { fatal: true }).decode(descriptorJsonBytes)) as Record<string, any>;
    const componentSha256 = createHash("sha256").update(componentBytes).digest("hex");
    const coreSha256 = createHash("sha256").update(coreBytes).digest("hex");
    if (projected.packageId !== request.componentPackageId || projected.manifest?.pluginId !== request.pluginId || typeof projected.manifest?.version !== "string" || projected.manifest.version.length === 0 || projected.role !== "plugin")
      throw new Error("fresh descriptor identity differs from the exact component request");
    verifyFreshCatalogPackageV1(descriptorJsonBytes, descriptorBytes, {
      pluginId: request.pluginId,
      packageId: request.componentPackageId,
      version: projected.manifest.version,
      role: "plugin",
      execution: "isolated",
      wasmSha256: componentSha256,
      coreWasmSha256: coreSha256,
    });
    check();
    const result = {
      componentBytes,
      descriptorBytes,
      componentSha256,
      componentBlake3: blake3Hex(componentBytes),
      descriptorSha256: createHash("sha256").update(descriptorBytes).digest("hex"),
      coreSha256,
      version: projected.manifest.version as string,
    };
    complete = true;
    return result;
  } finally {
    descriptorJsonBytes?.fill(0);
    if (!complete) descriptorBytes?.fill(0);
  }
}

/** 🫴️ Loans a private bounded copy once and drains its consumer before retiring the capability. */
async function withFreshComponentLease<T>(component: Uint8Array, control: FreshBuildControlV1, derive: (lease: FreshComponentLeaseV1) => Promise<T>): Promise<T> {
  let open = true,
    used = false,
    pending: Promise<unknown> | undefined;
  const lease: FreshComponentLeaseV1 = Object.freeze({
    consume<R>(consumer: (bytes: Uint8Array<ArrayBuffer>) => Promise<R>): Promise<R> {
      if (!open) return Promise.reject(new Error("fresh component lease expired"));
      if (used) return Promise.reject(new Error("fresh component lease already consumed"));
      used = true;
      const operation = (async () => {
        freshCheckpoint(control, "derive", 7, 8);
        const loan = new Uint8Array(component.byteLength);
        try {
          for (let offset = 0; offset < component.byteLength; offset += FRESH_IO_CHUNK_BYTES) {
            freshCheckpoint(control, "derive-copy", offset, component.byteLength);
            loan.set(component.subarray(offset, Math.min(offset + FRESH_IO_CHUNK_BYTES, component.byteLength)), offset);
          }
          freshCheckpoint(control, "derive", 7, 8);
          const result = await consumer(loan);
          freshCheckpoint(control, "derive", 8, 8);
          return result;
        } finally {
          loan.fill(0);
        }
      })();
      pending = operation;
      void operation.catch(() => {});
      return operation;
    },
  });
  try {
    freshCheckpoint(control, "derive", 7, 8);
    const result = await derive(lease);
    open = false;
    if (!used) throw new Error("fresh component lease was not consumed");
    await pending;
    freshCheckpoint(control, "derive", 8, 8);
    return result;
  } finally {
    open = false;
    await pending?.catch(() => {});
  }
}

/** 🧊️ Stages verified inputs, settles their required derivation and retires every source owner. */
export async function stageFreshComponentInputs<T>(
  request: Pick<FreshComponentRequestV1, "pluginId" | "componentPackageId">,
  snapshot: Awaited<ReturnType<typeof captureFreshComponentInputs>>,
  stageRoot: string,
  witExports: readonly string[],
  control: FreshBuildControlV1,
  derive: (lease: FreshComponentLeaseV1) => Promise<T>,
): Promise<FreshComponentProducedV1<T>> {
  const ownedFiles: string[] = [];
  try {
    const componentPath = join(stageRoot, "component.wasm"),
      descriptorPath = join(stageRoot, "descriptor.semio");
    const stagedComponent = freshStage(snapshot.componentBytes, componentPath, control, "stage-component", 5, 8);
    ownedFiles.push(componentPath);
    const stagedDescriptor = freshStage(snapshot.descriptorBytes, descriptorPath, control, "stage-descriptor", 6, 8);
    ownedFiles.push(descriptorPath);
    if (stagedComponent.sha256 !== snapshot.componentSha256 || stagedDescriptor.sha256 !== snapshot.descriptorSha256) throw new Error("fresh staged bytes differ from the verified snapshot");
    const receipt: FreshComponentReceiptV1 = Object.freeze({
      pluginId: request.pluginId,
      packageId: request.componentPackageId,
      version: snapshot.version,
      component: Object.freeze({ relativePath: "component.wasm", ...stagedComponent, blake3: snapshot.componentBlake3 }),
      descriptor: Object.freeze({ relativePath: "descriptor.semio", ...stagedDescriptor }),
      coreSha256: snapshot.coreSha256,
      witExports: Object.freeze([...witExports]),
    });
    const derived = await withFreshComponentLease(snapshot.componentBytes, control, derive);
    freshCheckpoint(control, "complete", 8, 8);
    return Object.freeze({ receipt, derived });
  } catch (error) {
    for (const path of ownedFiles) rmSync(path, { force: true });
    throw error;
  } finally {
    snapshot.componentBytes.fill(0);
    snapshot.descriptorBytes.fill(0);
  }
}

/** 🧬️ Builds and stages verified inputs, requiring derivation before its private raw owner retires. */
export async function produceFreshComponentV1<T>(
  repoRoot: string,
  request: FreshComponentRequestV1,
  freshTargetRoot: string,
  packageStageRoot: string,
  control: FreshBuildControlV1,
  derive: (lease: FreshComponentLeaseV1) => Promise<T>,
): Promise<FreshComponentProducedV1<T>> {
  if (typeof derive !== "function") throw new Error("fresh component derivation callback is required");
  if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/u.test(request.pluginId) || !/^semio:[a-z0-9]+(?:-[a-z0-9]+)*$/u.test(request.componentPackageId) || !/^[a-z0-9]+(?:-[a-z0-9]+)*$/u.test(request.cargoPackage) || !/^[a-z0-9_]+\.wasm$/u.test(request.outputName))
    throw new Error("fresh component request identity is not canonical");
  const targetRoot = freshRoot(freshTargetRoot, "fresh component target root");
  const stageRoot = freshRoot(packageStageRoot, "fresh component stage root");
  if (freshPathIsWithin(targetRoot, stageRoot) || freshPathIsWithin(stageRoot, targetRoot)) throw new Error("fresh component target and stage roots must be disjoint");
  if (control.diagnosticsRoot && (freshPathIsWithin(targetRoot, resolve(control.diagnosticsRoot)) || freshPathIsWithin(stageRoot, resolve(control.diagnosticsRoot)))) throw new Error("fresh process evidence must outlive target and stage cleanup");
  const workRoot = join(targetRoot, ".semio-fresh-component-work");
  mkdirSync(workRoot, { mode: 0o700 });
  const env = devToolingEnv({ CARGO_TARGET_DIR: targetRoot, CARGO_INCREMENTAL: "0" });
  const total = 8;
  let componentBytes: Uint8Array | undefined, coreBytes: Uint8Array | undefined, snapshot: Awaited<ReturnType<typeof captureFreshComponentInputs>> | undefined;
  try {
    const cargo = request.rootCdylib
      ? ["rustc", "-p", request.cargoPackage, "--lib", "--crate-type", "cdylib", "--target", "wasm32-wasip2", "--profile", request.componentProfile]
      : ["build", "-p", request.cargoPackage, "--target", "wasm32-wasip2", "--profile", request.componentProfile];
    const componentInvocation = await freshRun("cargo", cargo, repoRoot, env, control, "build", 0, total);
    const cargoComponent = pluginWasmArtifactPath(repoRoot, request.cargoPackage, request.componentProfile, targetRoot);
    if (cargoComponent !== join(targetRoot, "wasm32-wasip2", request.componentProfile, request.outputName)) throw new Error("fresh component output identity differs from the shared Cargo artifact path");
    freshWasmArtifactSize(cargoComponent, FRESH_COMPONENT_MAX_BYTES, "fresh WASIp2 component");
    componentBytes = readStableBuildFile(cargoComponent, FRESH_COMPONENT_MAX_BYTES, { remaining: FRESH_COMPONENT_MAX_BYTES }, () => freshCheckpoint(control, "snapshot", 1, total));
    if (!componentBytes.byteLength) throw new Error("fresh component is empty");
    const component = join(workRoot, "component.wasm");
    freshStage(componentBytes, component, control, "snapshot", 1, total);
    const jco = resolveWorkspaceBin("@bytecodealliance/jco", repoRoot);
    if (!jco) throw new Error("missing @bytecodealliance/jco workspace binary; run bun install");
    const extractRoot = join(workRoot, "extract");
    mkdirSync(extractRoot, { mode: 0o700 });
    const baseName = request.outputName.slice(0, -".wasm".length);
    await freshRun("node", [jco, "transpile", component, "-o", extractRoot, "--name", baseName, "--map", "semio:framework/pure=./pure.js", "--map", "semio:framework/host-async=./host-async.js"], repoRoot, env, control, "extract-core", 1, total);
    const corePath = join(extractRoot, `${baseName}.core.wasm`);
    freshWasmArtifactSize(corePath, FRESH_COMPONENT_MAX_BYTES, "fresh extracted core Wasm module");
    coreBytes = readStableBuildFile(corePath, FRESH_COMPONENT_MAX_BYTES, { remaining: FRESH_COMPONENT_MAX_BYTES }, () => freshCheckpoint(control, "snapshot-core", 2, total));
    if (!coreBytes.byteLength) throw new Error("fresh core module is empty");
    const core = join(workRoot, "core.wasm");
    freshStage(coreBytes, core, control, "snapshot-core", 2, total);
    const witPath = join(workRoot, "component.wit");
    await freshRun("node", [jco, "wit", component, "--output", witPath], repoRoot, env, control, "inspect-wit", 2, total);
    const wit = readFileSync(witPath, "utf8");
    if (Buffer.byteLength(wit) > FRESH_COMPONENT_MAX_BYTES) throw new Error("fresh component WIT exceeds its fixed boundary");
    const witExports = [...wit.matchAll(/\bexport\s+([^;]+);/gu)]
      .map((match) => {
        const token = match[1]!.trim();
        const iface = token.match(/\/([a-z][a-z0-9-]*)@/u)?.[1];
        return iface ?? token;
      })
      .sort();
    // 🧬️ `codec` joined `world actor`'s exports with the creation-path codec surface (ticket
    // 26/09/18): a component without it cannot answer `pack-schema-hash`/`genesis`/`print-mirror`/
    // `apply-ops`, so a hub that links no Rust codec for its package can neither create nor edit its
    // documents. Requiring it here is the earliest point the absence is visible — at the built
    // artifact, before a descriptor or a catalog generation is derived from it.
    if (!["checkpoint", "codec", "describe", "jobs", "reactor"].every((name) => witExports.includes(name))) throw new Error("fresh component omits a required actor export");
    const descriptorInvocation = await freshRun("cargo", ["build", "-p", CRATE_NAME], repoRoot, env, control, "build-descriptor-emitter", 3, total);
    const emitter = join(targetRoot, "debug", process.platform === "win32" ? `${CRATE_NAME}.exe` : CRATE_NAME);
    const descriptorRoot = join(workRoot, "descriptor");
    mkdirSync(descriptorRoot, { mode: 0o700 });
    await freshRun(emitter, ["describe", component, "--core", core, "--out", descriptorRoot], repoRoot, env, control, "emit-descriptor", 4, total);
    const descriptorPack = join(descriptorRoot, DESCRIPTOR_PACK_FILENAME);
    const descriptorJson = join(descriptorRoot, DESCRIPTOR_JSON_FILENAME);
    snapshot = await captureFreshComponentInputs(repoRoot, request, componentBytes, coreBytes, { descriptorPack, descriptorJson }, control);
    const produced = await stageFreshComponentInputs(request, snapshot, stageRoot, witExports, control, derive);
    if (!componentInvocation || !descriptorInvocation) throw new Error("fresh component compiler observations are missing");
    return { ...produced, compilerInvocations: [componentInvocation, descriptorInvocation] };
  } finally {
    componentBytes?.fill(0);
    coreBytes?.fill(0);
    snapshot?.descriptorBytes.fill(0);
    rmSync(workRoot, { recursive: true, force: true });
  }
}

/** 🛂️ The ONE describe route of every plugin and extension component (the inferred Nx `describe` target, which
 * `dependsOn` `component-dev`): reads the exact bytes `component-dev` staged at `<crate>/dist/component-dev/<crate>.wasm`,
 * extracts its core with jco and re-emits `🛂️.descriptor.semio` + `🔣️.json` at the owner root (`<owner>/📦️packages/🦀️rust`
 * is the crate). No build happens here, so the committed descriptor, the `materialize-dev` staging (which reads the same
 * deliverable) and every consumer that resolves `dist/component-dev` describe one build by construction. */
export function describeComponentDeliverable(repoRoot: string, manifest: string, control: DescriptorEmissionControlV1 = {}): number {
  const manifestPath = resolve(repoRoot, manifest);
  try {
    const cargo = createRequire(import.meta.url)("@iarna/toml").parse(readFileSync(manifestPath, "utf8")) as { package?: { name?: string; metadata?: { component?: { package?: string }; semio?: { "component-kind"?: string } } } };
    const packageName = cargo.package?.name;
    if (!packageName || !cargo.package?.metadata?.component?.package || !["plugin", "extension"].includes(cargo.package.metadata.semio?.["component-kind"] ?? "")) throw new Error(`${manifest} has no authored plugin or extension component kind`);
    const crateRoot = dirname(manifestPath);
    const deliverableRoot = join(crateRoot, "dist");
    const component = join(deliverableRoot, "component-dev", `${packageName.replace(/-/g, "_")}.wasm`);
    if (!existsSync(component)) throw new Error(`no component-dev deliverable at ${relative(repoRoot, component)}; describe runs through Nx, which builds component-dev first`);
    const scratch = mkdtempSync(join(deliverableRoot, ".semio-describe-core-"));
    try {
      const core = extractPluginCore(repoRoot, component, scratch, packageName.replace(/-/g, "_"));
      const receipt = emitOwnerDescriptorPairV1(repoRoot, { rawComponentPath: component, extractedCorePath: core, ownerRoot: resolve(crateRoot, "..", ".."), artifactRoot: deliverableRoot }, control);
      console.log(`described ${receipt.pluginId} (${receipt.role} ${receipt.packageId}@${receipt.version}) from ${relative(repoRoot, component)} -> ${relative(repoRoot, receipt.ownerRoot)} (wasm=${receipt.rawSha256} core=${receipt.coreSha256} descriptor=${receipt.descriptorSha256})`);
      return 0;
    } finally {
      rmSync(scratch, { recursive: true, force: true });
    }
  } catch (error) {
    console.error(`describe ${manifest} failed: ${(error as Error).message}`);
    return 1;
  }
}

/** 🛂️ `describe component --manifest <Cargo.toml>`: the command the inferred Nx `describe` target of every component runs. */
export class DescribeComponentScript extends BundleScript {
  run(segments: string[]): void {
    if (segments.length !== 2 || segments[0] !== "--manifest") throw new Error("usage: component --manifest <Cargo.toml>");
    process.exit(describeComponentDeliverable(this.repoRoot, segments[1]!));
  }
}

import { createHash } from "node:crypto";
import { closeSync, existsSync, mkdirSync, mkdtempSync, openSync, readFileSync, readdirSync, renameSync, rmSync, writeFileSync, cpSync } from "node:fs";
import { isAbsolute, join, resolve } from "node:path";
import { acquireCargoBuildLeaseV1 } from "../../../../../../../🔨️modules/🏃️process/📦️artifacts/🏗️native-build/🔒️lease/🟦️.ts";
import { repoCacheDirectory } from "../../../../../../🦑️repo/🔨️modules/📚️library/⚡️caching/🟦️.ts";
import { readStableBuildFile } from "../../../../../../🦑️repo/🔨️modules/📚️library/📦️packages/🟦️typescript/🟦️.ts";
import { semanticOwnedInputFileSnapshot } from "../../../../../../🦑️repo/🔨️modules/📚️library/🔍️discovery/🟦️.ts";
import { FRESH_COMPONENT_MAX_BYTES, FRESH_IO_CHUNK_BYTES, freshWasmArtifactSize } from "../../🏗️component-build/🟦️.ts";
import { FRESH_SOURCE_EPOCH_LIMITS, captureFreshSourceEpochV1, freshSourceEpochBytesV1, freshSourceOrderedJson, parseFreshRustDepInfoV1 } from "../../🧾️source-epoch/🟦️.ts";
import { captureFreshComponentInputs, freshRun, freshStage, stageFreshComponentInputs } from "../../🏭️fresh-component/🟦️.ts";

export function createFreshComponentTests() {
  const source = { directory: resolve(import.meta.dir, "../../📦️packages/🦀️rust") };
  function testArtifactRoot(repoRoot: string): string {
    const root = process.env.SEMIO_TEST_ARTIFACT_DIR ?? repoCacheDirectory(repoRoot, "tests", "fresh-component", "🗑️generated");
    mkdirSync(root, { recursive: true });
    return root;
  }
  type FreshSourceEpochLawsFixtureV1 = Readonly<{
    limits: Readonly<{ fileBytes: number; totalBytes: number; files: number; legs: number }>;
    files: readonly Readonly<{ path: string; text: string }>[];
    legs: readonly Readonly<{ id: string; package: string; args: readonly string[]; inputs: readonly string[] }>[];
    cases: readonly string[];
  }>;
  type FreshStagingFixtureV1 = Readonly<{
    appChannelVersion: number;
    componentHex: string;
    componentSha256: string;
    componentBlake3: string;
    coreHex: string;
    laws: readonly string[];
  }>;
  type FreshProcessFixtureV1 = Readonly<{
    maxOutputBytes: number;
    diagnosticChars: number;
    cargoProvenance: Readonly<{name:string;stdout:string;source:string;buildSource:string;compilerEnv:string}>;
    cargoOwnership: Readonly<{rootName:string;nestedName:string;missingName:string;stdout:string;source:string}>;
    queuedCargoCases: readonly Readonly<{ name: string; mode: "cancel" | "timeout" }>[];
    cases: readonly Readonly<{ name: string; mode: "exit" | "missing" | "cancel" | "timeout" | "flood" | "pre-cancel"; stdout: string; stderr: string; exitCode: number; reason: "exit" | "spawn-error" | "cancelled" | "timeout" | "output-limit"; diagnostic: string }>[];
  }>;
  type RustDepInfoLawsFixtureV1 = Readonly<{ maximumBytes: number; cases: readonly Readonly<{ id: string; text: string; expected: unknown }>[] }>;
  type FreshBuildControlV1 = import("../../🧾️source-epoch/🟦️.ts").FreshBuildControlV1;
  type FreshComponentLeaseV1 = import("../../🧾️source-epoch/🟦️.ts").FreshComponentLeaseV1;
  type FreshSourceEpochLegV1 = import("../../🧾️source-epoch/🟦️.ts").FreshSourceEpochLegV1;
  type FreshSourceEpochPlanV1 = import("../../🧾️source-epoch/🟦️.ts").FreshSourceEpochPlanV1;
  /** 🧪️ Exercises the physical epoch owner against neutral races and independent canonical/hash oracles. */
  async function testFreshComponentSourceEpochV1(repoRoot: string): Promise<void> {
    const assert: typeof import("node:assert/strict") = (await import("node:assert/strict")).default;
    const { default: stableStringify } = await import("fast-json-stable-stringify");
    const { dirname } = await import("node:path");
    const { symlinkSync, ftruncateSync } = await import("node:fs");
    const fixtureRoot = resolve(source.directory, "../../🧫️fixtures/🧾️fresh-source-epoch");
    const fixture: FreshSourceEpochLawsFixtureV1 = JSON.parse(readFileSync(join(fixtureRoot, "🔣️.json"), "utf8"));
    const { default: Ajv } = await import("ajv");
    const ajv = new Ajv({ strict: true, allErrors: true });
    const describeSchema = JSON.parse(readFileSync(resolve(source.directory, "../../🧬️schema/🔣️.json"), "utf8"));
    ajv.addSchema(describeSchema);
    const validateEpoch = ajv.compile({ $ref: `${describeSchema.$id}#/$defs/FreshSourceEpochV1` });
    assert.deepEqual(fixture.limits, FRESH_SOURCE_EPOCH_LIMITS);
    const depInfo: RustDepInfoLawsFixtureV1 = JSON.parse(readFileSync(join(fixtureRoot, "📃️dep-info.json"), "utf8"));
    for (const row of depInfo.cases) {
      const bytes = Buffer.from(row.text);
      if (row.expected === null) assert.throws(() => parseFreshRustDepInfoV1(bytes, () => {}), row.id);
      else assert.equal(stableStringify(parseFreshRustDepInfoV1(bytes, () => {})), stableStringify(row.expected), row.id);
    }
    assert.throws(() => parseFreshRustDepInfoV1(new Uint8Array([0xff, 0x0a]), () => {}), "lossy UTF-8");
    assert.throws(() => parseFreshRustDepInfoV1(new Uint8Array(depInfo.maximumBytes + 1), () => {}), "dep-info byte bound");
    assert.throws(() => parseFreshRustDepInfoV1(Buffer.from(depInfo.cases[0].text), () => { throw new Error("dep-info cancelled"); }), /dep-info cancelled/);
    const artifactRoot = testArtifactRoot(repoRoot);
    assert(artifactRoot && isAbsolute(artifactRoot) && artifactRoot.split(/[\\/]/u).includes("🗑️generated"));
    const evidence = mkdtempSync(join(artifactRoot, "fresh-source-epoch-"));
    const legs: FreshSourceEpochLegV1[] = fixture.legs.map(({ id, package: cargoPackage, args }) => ({ id, package: cargoPackage, args }));
    const environment = [["CARGO_INCREMENTAL", "0"], ["RUSTC_WRAPPER", ""], ["RUSTFLAGS", null]] as const;
    const plan: FreshSourceEpochPlanV1 = { toolchain: { cargo: "cargo fixture", rustc: "rustc fixture" }, environment, legs, files: fixture.files.map((file) => file.path) };
    for (const name of fixture.cases) {
      const root = join(evidence, name);
      mkdirSync(root);
      for (const file of fixture.files) {
        const path = join(root, file.path);
        mkdirSync(dirname(path), { recursive: true });
        writeFileSync(path, file.text, { flag: "wx", mode: 0o600 });
      }
      const pointer = join(root, "current.json"), prior = Buffer.from("unpublished-epoch-fixture\n");
      writeFileSync(pointer, prior, { flag: "wx", mode: 0o600 });
      let cancelled = false, expired = false;
      const control: FreshBuildControlV1 = { cancelled: () => cancelled, remainingMs: () => expired ? 0 : 10000, checkpoint() {} };
      const owner = captureFreshSourceEpochV1(root, plan, control);
      assert(validateEpoch(owner.record), JSON.stringify(validateEpoch.errors));
      assert(Object.isFrozen(owner) && Object.isFrozen(owner.record) && owner.record.files.every(Object.isFrozen));
      const mutate = (): void => writeFileSync(join(root, "artifacts/🦀️.rs"), "pub const CHANNEL_VERSION: u32 = 15;\n");
      const start = (index: number): void => owner.start(legs[index]!, environment);
      const complete = (index: number): void => owner.complete(legs[index]!.id, fixture.legs[index].inputs);
      const run = (index: number): void => { start(index); complete(index); };
      if (name === "shared-epoch") {
        assert.equal(freshSourceOrderedJson(owner.record), stableStringify(owner.record));
        const fields = [owner.record.schema, stableStringify(owner.record.toolchain), stableStringify(owner.record.environment), stableStringify(owner.record.legs), stableStringify(owner.record.files)];
        const parts = fields.map((field) => new TextEncoder().encode(field));
        const oracle = new Uint8Array(parts.reduce((sum, bytes) => sum + bytes.length + 4, 0));
        let offset = 0;
        for (const bytes of parts) { new DataView(oracle.buffer).setUint32(offset, bytes.length, false); oracle.set(bytes, offset + 4); offset += bytes.length + 4; }
        assert.deepEqual(Buffer.from(freshSourceEpochBytesV1(owner.record)), Buffer.from(oracle));
        assert.notDeepEqual(Buffer.from(freshSourceEpochBytesV1({ ...owner.record, legs: [...owner.record.legs].reverse() })), Buffer.from(oracle));
        assert.equal(owner.digest, Buffer.from(await crypto.subtle.digest("SHA-256", oracle)).toString("hex"));
        run(0); run(1);
        assert.equal(owner.finish(), owner.digest);
        assert.throws(() => owner.finish(), /closed/);
      } else {
        assert.throws(() => {
          if (name === "changed-before-first") { mutate(); start(0); }
          else if (name === "changed-between-legs") { run(0); mutate(); start(1); }
          else if (name === "changed-after-last") { run(0); run(1); mutate(); owner.finish(); }
          else if (name === "unknown-compiler-input") { start(0); owner.complete(legs[0]!.id, [...fixture.legs[0].inputs, "unknown/🦀️.rs"]); }
          else if (name === "missing-input") { rmSync(join(root, "Cargo.lock")); start(0); }
          else if (name === "same-bytes-name-replacement") { const path = join(root, "Cargo.lock"); renameSync(path, path + ".retained"); writeFileSync(path, readFileSync(path + ".retained")); start(0); }
          else if (name === "linked-parent") { const path = join(root, "assets"); renameSync(path, path + "-retained"); symlinkSync(path + "-retained", path, process.platform === "win32" ? "junction" : "dir"); start(0); }
          else if (name === "oversized-input") { const file = openSync(join(root, "Cargo.lock"), "r+"); try { ftruncateSync(file, fixture.limits.fileBytes + 1); } finally { closeSync(file); } start(0); }
          else if (name === "changed-arguments") owner.start({ ...legs[0]!, args: [...legs[0]!.args, "--features", "foreign"] }, environment);
          else if (name === "changed-environment") owner.start(legs[0]!, [["RUSTFLAGS", "--cfg foreign"]]);
          else if (name === "out-of-order-leg") start(1);
          else if (name === "duplicate-leg-completion") { run(0); complete(0); }
          else if (name === "incomplete-finish") { run(0); owner.finish(); }
          else if (name === "cancelled") { cancelled = true; start(0); }
          else if (name === "deadline") { expired = true; start(0); }
          else if (name === "closed-owner") { owner.abort(); start(0); }
          else assert.fail("unknown epoch law " + name);
        }, name);
        assert.throws(() => owner.finish(), /closed/, name + " terminal refusal");
      }
      assert.deepEqual(readFileSync(pointer), prior, name + " pointer is untouched");
    }
    const bounded = join(evidence, "bounded");
    mkdirSync(bounded);
    writeFileSync(join(bounded, "input.rs"), Buffer.alloc(2 * FRESH_IO_CHUNK_BYTES + 1, 65));
    assert.throws(() => semanticOwnedInputFileSnapshot(bounded, "input.rs", { maximumBytes: FRESH_IO_CHUNK_BYTES }), /byte boundary/);
    let checks = 0;
    assert.throws(() => semanticOwnedInputFileSnapshot(bounded, "input.rs", { maximumBytes: 3 * FRESH_IO_CHUNK_BYTES, checkpoint() { if (++checks === 4) throw new Error("bounded snapshot cancellation"); } }), /bounded snapshot cancellation/);
    assert.equal(checks, 4);
    for (const path of ["../foreign.rs", "/foreign.rs", "C:/foreign.rs", "a\\foreign.rs", "node_modules/source.rs", "target/source.rs", "🗑️generated/source.rs"]) assert.throws(() => captureFreshSourceEpochV1(bounded, { ...plan, files: [path] }, { cancelled: () => false, remainingMs: () => 10000, checkpoint() {} }), /coordinate|refuses/);
    console.log(`fresh-source-epoch: AJV=1 stable-stringify=1 WebCrypto=1 physical-laws=${fixture.cases.length} bounded-capture=2 unsafe-paths=7 dep-info=${depInfo.cases.length}+3 evidence=${evidence}; Cargo resolver/dep-info integration remains unqualified`);
  }

  /** 🧪️ Qualifies retained verified inputs and staging independently of Cargo or descriptor execution. */
  async function testFreshComponentStagingV1(repoRoot: string): Promise<void> {
    const assert: typeof import("node:assert/strict") = (await import("node:assert/strict")).default;
    const { encodePackValue } = await import("../../../../../🟦️.ts");
    const fixtureRoot = resolve(source.directory, "../../🧫️fixtures/🧊️fresh-staging");
    const fixture: FreshStagingFixtureV1 = JSON.parse(readFileSync(join(fixtureRoot, "🔣️.json"), "utf8"));
    const artifactRoot = testArtifactRoot(repoRoot);
    assert(artifactRoot !== undefined && artifactRoot.includes("🗑️generated"));
    mkdirSync(artifactRoot, { recursive: true });
    const evidence = mkdtempSync(join(artifactRoot, "fresh-component-staging-"));
    const component = Buffer.from(fixture.componentHex, "hex"),
      core = Buffer.from(fixture.coreHex, "hex");
    const descriptor = {
      descriptorVersion: 1,
      packageId: "semio:gis",
      role: "plugin",
      manifest: { pluginId: "gis", label: "GIS", version: "0.1.0", apps: [], examples: [], capabilities: [], topicContributions: [], commands: [], artifactKinds: [], dependencies: [], contributions: [] },
      activationEvents: [],
      capabilityRequests: [],
      extensionPoints: [],
      execution: "isolated",
      executionProtocol: { appChannelVersion: fixture.appChannelVersion },
      quotas: {},
      contributions: {},
      assets: [],
      hashes: { wasmSha256: fixture.componentSha256, coreWasmSha256: createHash("sha256").update(core).digest("hex"), descriptorSha256: "" },
    };
    descriptor.hashes.descriptorSha256 = createHash("sha256").update(encodePackValue(descriptor)).digest("hex");
    const descriptorBytes = encodePackValue(descriptor);
    const paths = { component: join(evidence, "component.wasm"), core: join(evidence, "core.wasm"), descriptorPack: join(evidence, "descriptor.semio"), descriptorJson: join(evidence, "descriptor.json") };
    for (const [key, bytes] of [
      ["component", component],
      ["core", core],
      ["descriptorPack", descriptorBytes],
      ["descriptorJson", Buffer.from(JSON.stringify(descriptor))],
    ] as const)
      writeFileSync(paths[key], bytes);
    assert.equal(freshWasmArtifactSize(paths.component, component.byteLength, "fixture WASIp2 component"), component.byteLength);
    assert.throws(() => freshWasmArtifactSize(paths.component, component.byteLength - 1, "fixture WASIp2 component"), new RegExp(`byteLength=${component.byteLength} maximum=${component.byteLength - 1}`));
    const control: FreshBuildControlV1 = { cancelled: () => false, remainingMs: () => 60_000, checkpoint() {} };
    const capturedComponent = readStableBuildFile(paths.component, FRESH_COMPONENT_MAX_BYTES, { remaining: FRESH_COMPONENT_MAX_BYTES }, () => {});
    const capturedCore = readStableBuildFile(paths.core, FRESH_COMPONENT_MAX_BYTES, { remaining: FRESH_COMPONENT_MAX_BYTES }, () => {});
    writeFileSync(paths.core, "replaced-core");
    const snapshot = await captureFreshComponentInputs(repoRoot, { pluginId: "gis", componentPackageId: "semio:gis" }, capturedComponent, capturedCore, paths, control);
    assert.equal(snapshot.coreSha256, descriptor.hashes.coreWasmSha256);
    assert.equal(snapshot.componentSha256, fixture.componentSha256);
    assert.equal(snapshot.componentBlake3, fixture.componentBlake3);
    assert.equal(snapshot.componentSha256, Buffer.from(await crypto.subtle.digest("SHA-256", component)).toString("hex"));
    assert.deepEqual(Buffer.from(snapshot.descriptorBytes), Buffer.from(descriptorBytes));
    for (const path of Object.values(paths)) {
      renameSync(path, path + ".retained");
      writeFileSync(path, "replaced-source");
    }
    const destination = join(evidence, "staged.semio");
    const staged = freshStage(snapshot.descriptorBytes, destination, control, "stage-descriptor", 6, 8);
    assert.equal(staged.sha256, Buffer.from(await crypto.subtle.digest("SHA-256", descriptorBytes)).toString("hex"));
    assert.deepEqual(readFileSync(destination), Buffer.from(descriptorBytes));
    renameSync(destination, destination + ".retained");
    writeFileSync(destination, "replaced-stage");
    assert.deepEqual(Buffer.from(snapshot.descriptorBytes), Buffer.from(descriptorBytes));
    assert.equal(createHash("sha256").update(snapshot.componentBytes).digest("hex"), fixture.componentSha256);
    const cancelled = join(evidence, "cancelled.semio");
    let checkpoints = 0;
    assert.throws(
      () =>
        freshStage(
          snapshot.descriptorBytes,
          cancelled,
          {
            ...control,
            cancelled: () => checkpoints >= 2,
            checkpoint() {
              checkpoints++;
            },
          },
          "stage-descriptor",
          6,
          8,
        ),
      /cancelled/,
    );
    assert.equal(checkpoints, 2);
    assert.equal(existsSync(cancelled), false);
    writeFileSync(paths.component, component);
    writeFileSync(paths.core, core);
    writeFileSync(paths.descriptorPack, descriptorBytes);
    writeFileSync(paths.descriptorJson, JSON.stringify({ ...descriptor, packageId: "semio:foreign" }));
    await assert.rejects(captureFreshComponentInputs(repoRoot, { pluginId: "gis", componentPackageId: "semio:gis" }, capturedComponent, capturedCore, paths, control), /identity/);
    const cloneSnapshot = () => ({ ...snapshot, componentBytes: Uint8Array.from(component), descriptorBytes: Uint8Array.from(descriptorBytes) });
    const handoff = async <T>(name: string, input: ReturnType<typeof cloneSnapshot>, buildControl: FreshBuildControlV1, derive: (lease: FreshComponentLeaseV1) => Promise<T>) => {
      const stage = join(evidence, name);
      mkdirSync(stage);
      return await stageFreshComponentInputs({ pluginId: "gis", componentPackageId: "semio:gis" }, input, stage, ["checkpoint", "describe", "jobs", "reactor"], buildControl, derive);
    };
    let retainedLease: FreshComponentLeaseV1 | undefined, retainedLoan: Uint8Array<ArrayBuffer> | undefined;
    const retainedInput = cloneSnapshot();
    const produced = await handoff("loan-success", retainedInput, control, async (lease) => {
      retainedLease = lease;
      assert.deepEqual(Object.keys(lease), ["consume"]);
      assert(Object.isFrozen(lease));
      const digest = await lease.consume(async (bytes) => {
        retainedLoan = bytes;
        assert.notEqual(bytes.buffer, retainedInput.componentBytes.buffer);
        const sha256 = Buffer.from(await crypto.subtle.digest("SHA-256", bytes)).toString("hex");
        bytes.fill(9);
        assert.deepEqual(Buffer.from(retainedInput.componentBytes), component);
        return sha256;
      });
      await assert.rejects(
        lease.consume(async () => "second"),
        /already consumed/,
      );
      return digest;
    });
    assert.equal(produced.derived, produced.receipt.component.sha256);
    assert.equal(produced.receipt.component.sha256, fixture.componentSha256);
    assert.deepEqual(readFileSync(join(evidence, "loan-success/component.wasm")), component);
    assert.deepEqual(Object.keys(produced.receipt).sort(), ["component", "coreSha256", "descriptor", "packageId", "pluginId", "version", "witExports"]);
    assert(retainedLoan!.every((byte) => byte === 0));
    assert(retainedInput.componentBytes.every((byte) => byte === 0));
    assert(retainedInput.descriptorBytes.every((byte) => byte === 0));
    await assert.rejects(
      retainedLease!.consume(async () => "late"),
      /expired/,
    );
    const rejectedSource = cloneSnapshot();
    let rejectedLoan: Uint8Array | undefined;
    await assert.rejects(
      handoff("loan-rejected", rejectedSource, control, (lease) =>
        lease.consume(async (bytes) => {
          rejectedLoan = bytes;
          throw new Error("derive sentinel");
        }),
      ),
      /^Error: derive sentinel$/,
    );
    assert(rejectedLoan!.every((byte) => byte === 0));
    assert(rejectedSource.componentBytes.every((byte) => byte === 0));
    assert(rejectedSource.descriptorBytes.every((byte) => byte === 0));
    assert.deepEqual(readdirSync(join(evidence, "loan-rejected")), []);
    for (const when of ["before-consume", "after-consume"] as const) {
      let stop = false,
        invoked = false;
      const cancelledSource = cloneSnapshot();
      await assert.rejects(
        handoff(`loan-cancel-${when}`, cancelledSource, { ...control, cancelled: () => stop }, async (lease) => {
          if (when === "before-consume") stop = true;
          return await lease.consume(async () => {
            invoked = true;
            stop = true;
            return "must not publish";
          });
        }),
        /cancelled/,
      );
      assert.equal(invoked, when === "after-consume");
      assert(cancelledSource.componentBytes.every((byte) => byte === 0));
      assert(cancelledSource.descriptorBytes.every((byte) => byte === 0));
      assert.deepEqual(readdirSync(join(evidence, `loan-cancel-${when}`)), []);
    }
    for (const failure of [false, true]) {
      const unawaitedSource = cloneSnapshot();
      let release!: () => void,
        entered!: () => void,
        settled = false,
        loan: Uint8Array | undefined;
      const gate = new Promise<void>((resolve) => {
        release = resolve;
      });
      const running = new Promise<void>((resolve) => {
        entered = resolve;
      });
      const operation = handoff(`loan-unawaited-${failure}`, unawaitedSource, control, async (lease) => {
        void lease.consume(async (bytes) => {
          loan = bytes;
          entered();
          await gate;
          if (failure) throw new Error("unawaited sentinel");
          return "done";
        });
        return "callback finished";
      });
      void operation.then(
        () => {
          settled = true;
        },
        () => {
          settled = true;
        },
      );
      await running;
      await Promise.resolve();
      assert.equal(settled, false);
      assert.deepEqual(Buffer.from(loan!), component);
      release();
      if (failure) await assert.rejects(operation, /^Error: unawaited sentinel$/);
      else assert.equal((await operation).derived, "callback finished");
      assert(loan!.every((byte) => byte === 0));
      assert(unawaitedSource.componentBytes.every((byte) => byte === 0));
      if (failure) assert.deepEqual(readdirSync(join(evidence, `loan-unawaited-${failure}`)), []);
    }
    snapshot.componentBytes.fill(0);
    capturedCore.fill(0);
    snapshot.descriptorBytes.fill(0);
    console.log(`fresh-component-staging: WebCrypto=1 Pack=1 BLAKE3=1 laws=${fixture.laws.length} evidence=${evidence}`);
  }

  /** 🧪️ Qualifies bounded process retirement and refuses Cargo startup after queued cancellation or deadline. */
  async function testFreshComponentProcessV1(repoRoot: string): Promise<void> {
    const assert: typeof import("node:assert/strict") = (await import("node:assert/strict")).default;
    const { default: deepEqual } = await import("fast-deep-equal");
    const fixtureRoot = resolve(source.directory, "../../🧫️fixtures/🧵️fresh-process");
    const fixture: FreshProcessFixtureV1 = JSON.parse(readFileSync(join(fixtureRoot, "🔣️.json"), "utf8"));
    const artifactRoot = testArtifactRoot(repoRoot);
    assert(artifactRoot && isAbsolute(artifactRoot) && artifactRoot.split(/[\\/]/u).includes("🗑️generated"));
    const evidence = mkdtempSync(join(artifactRoot, "fresh-process-laws-"));
    for (const row of fixture.cases) {
      const root = join(evidence, row.name);
      mkdirSync(root);
      const started = Date.now(),
        checkpoints: number[] = [];
      const deadline = started + (row.mode === "timeout" ? 150 : 10_000);
      const control: FreshBuildControlV1 = {
        diagnosticsRoot: root,
        cancelled: () => row.mode === "pre-cancel" || (row.mode === "cancel" && Date.now() - started >= 150),
        remainingMs: () => deadline - Date.now(),
        checkpoint: (_stage, completed) => {
          checkpoints.push(completed);
        },
      };
      const script =
        row.mode === "exit"
          ? "process.stdout.write(" + JSON.stringify(row.stdout) + "); process.stderr.write(" + JSON.stringify(row.stderr) + "); process.exitCode=" + row.exitCode
          : row.mode === "flood"
            ? "const {writeSync}=require('node:fs'); const b=Buffer.alloc(65536,120); for(let n=0;n<=1024;n++) writeSync(1,b); setInterval(()=>{},1000)"
            : "setInterval(()=>{},1000)";
      let failure: Error | undefined;
      try {
        await freshRun(
          row.mode === "missing" ? join(root, "absent-executable") : process.execPath,
          ["-e", script],
          repoRoot,
          { ...process.env, SEMIO_TEST_ARTIFACT_DIR: join(root, "must-not-use-ambient-evidence"), CARGO_TARGET_DIR: root },
          control,
          row.name,
          0,
          1,
        );
      } catch (error) {
        failure = error as Error;
      }
      assert(Date.now() - started < 6000, row.name + " bounded retirement");
      if (row.mode === "pre-cancel") {
        assert(failure?.message.includes(row.diagnostic));
        assert.deepEqual(readdirSync(root), []);
        continue;
      }
      const traces = readdirSync(root);
      assert.equal(traces.length, 1, row.name + " retained process trace");
      const trace = join(root, traces[0]!);
      const outcome = JSON.parse(readFileSync(join(trace, "outcome.json"), "utf8"));
      assert.equal(outcome.reason, row.reason);
      assert.equal(outcome.stage, row.name);
      assert.equal(outcome.cargoTargetDir, root);
      const stdout = readFileSync(join(trace, "stdout.jsonl"), "utf8"),
